frappe.ui.form.on("Journal Entry", {
    // setup(frm) {
    //     console.log("Set up event is running fine.");
    // },
    // before_load(frm) {
    //   console.log("Before Load event is running fine.");
    // },
    // onload(frm) {
    //     console.log("On Load event is running fine");
    // },
    onload(frm) {
        
        console.log('Document status: ' + frm.doc.docstatus);
        
        if (frm.doc.docstatus > 0) return; // Only for Draft

        // Hide default Save button
        // frm.page.wrapper.find('button[data-label="Save"]').hide();
        frm.disable_save();

        // Delay adding custom buttons until Quick Entry is rendered
        wait_for_quick_entry(() => add_custom_buttons(frm));
    },
    after_save(frm) {
        console.log("after_save triggered. docstatus =", frm.doc.docstatus);
        if (frm.doc.docstatus === 0) {
            // Soft refresh ensures buttons are properly added after save
            frm.reload_doc().then(() => {
                wait_for_quick_entry(() => add_custom_buttons(frm));
            });
        }
    }
});

// Poll DOM for Quick Entry button
function wait_for_quick_entry(callback, attempts = 10) {
    let quick_entry_btn = $('.btn[data-label="Quick%20Entry"]');

    if (quick_entry_btn.length) {
        callback();
    } else if (attempts > 0) {
        setTimeout(() => wait_for_quick_entry(callback, attempts - 1), 200);
    } else {
        console.warn("Quick Entry button not found after multiple attempts.");
    }
}

function add_custom_buttons(frm) {
    let quick_entry_btn = $('.btn[data-label="Quick%20Entry"]');

    if (!quick_entry_btn.length) return;

    // Avoid duplicate buttons
    if (quick_entry_btn.next().hasClass("custom-draft-btn")) return;

    // Save as Draft button
    let draft_btn = $('<button class="btn btn-default btn-sm custom-draft-btn">Save as Draft</button>');
    draft_btn.on("click", function() {
        console.log("Save as Draft clicked.");
        frm.save()
            .then(() => console.log("Saved as Draft. docstatus =", frm.doc.docstatus))
            .catch(err => console.error("Error saving draft:", err));
    });

    // Submit button
    let submit_btn = $('<button class="btn btn-primary btn-sm custom-submit-btn">Submit</button>');
    submit_btn.on("click", function() {
        console.log("Submit clicked.");
        frappe.confirm(
            __("Are you sure you want to submit this Journal Entry?"),
            () => {
                frm.save('Submit')
                    .then(() => console.log("Document submitted. docstatus =", frm.doc.docstatus))
                    .catch(err => console.error("Error submitting:", err));
            }
        );
    });

    // Insert buttons after Quick Entry
    draft_btn.insertAfter(quick_entry_btn);
    submit_btn.insertAfter(draft_btn);

    console.log("Custom buttons added after Quick Entry.");
}

frappe.ui.form.on("Journal Entry", {
    from_template(frm) {
        if (!frm.doc.from_template) return;

        frappe.db.get_doc("Journal Entry Template", frm.doc.from_template)
            .then(template => {

                if (!template.accounts) return;

                frm.doc.accounts.forEach((je_row, idx) => {

                    let t_row = template.accounts[idx];

                    // Reset previous highlights
                    remove_highlight(idx + 1, "debit_in_account_currency");
                    remove_highlight(idx + 1, "credit_in_account_currency");

                    // ---------- UPDATE COLUMNS ----------
                    if (t_row) {
                        je_row.sub_account = t_row.sub_account;
                        je_row.from_account = t_row.from_account;
                        je_row.to_account = t_row.to_account;

                        // ---------- HIGHLIGHT ONLY CORRECT CELLS ----------
                        if (t_row.debit_or_credit === "Debit") {
                            highlight_static(idx + 1, "debit_in_account_currency");
                        }
                        if (t_row.debit_or_credit === "Credit") {
                            highlight_static(idx + 1, "credit_in_account_currency");
                        }
                    }
                });

                frm.refresh_field("accounts");
            });
    }
});


// Highlight a cell
function highlight_static(row_idx, fieldname) {
    setTimeout(() => {
        let cell = $(`.grid-row[data-idx="${row_idx}"] .col[data-fieldname="${fieldname}"]`);
        if (cell.length) {
            cell.css({
                "background-color": "#fffac2",
                "font-weight": "bold",
                "border-radius": "4px"
            });
        }
    }, 300);
}

// Remove highlight from a cell
function remove_highlight(row_idx, fieldname) {
    let cell = $(`.grid-row[data-idx="${row_idx}"] .col[data-fieldname="${fieldname}"]`);
    cell.css({
        "background-color": "",
        "font-weight": "",
        "border-radius": ""
    });
}

frappe.ui.form.on('User', {
    refresh: function(frm) {
        // Wait for Frappe to render the top buttons
        setTimeout(() => {
            frm.page.wrapper.find('.btn.btn-default.ellipsis').each(function() {
                const btnText = $(this).clone().children().remove().end().text().trim();
                if (btnText === 'Permissions') {
                    $(this).hide();
                }
            });
        }, 500);
    }
});

frappe.ui.form.on('User', {
    onload: function(frm) {
        // Check if logged-in user has WH Admin role
        if (frappe.user.has_role('WH Admin')) {
            // Hide the Security Settings section
            const security_section = frm.fields_dict['security_settings_section'];
            if (security_section && security_section.wrapper) {
                $(security_section.wrapper).hide();
            }

            // OR simpler: hide by label text (in case section name differs)
            $('div.section-head:contains("Security Settings")').closest('.form-section').hide();
        }
    }
});

/* --------------------------------------------------------------
   GLOBAL SIDEBAR + HOME-CARD FILTER
   Works for every user (except Administrator)
   -------------------------------------------------------------- */
frappe.ready(() => {
    // -----------------------------------------------------------------
    // 1. CONFIG – add / remove roles and the workspaces they may see
    // -----------------------------------------------------------------
    const ROLE_WORKSPACES = {
        // role (exact name) → array of workspace labels that are allowed
        "WH ADMIN":   ["Home", "Users"],
        "Finance":    ["Home", "Accounts"],
        "Operations": ["Home", "Projects"],
        "Legal":      ["Home", "Documents"],
        "Advisor":    ["Home", "CRM"]
        // add more roles here …
    };

    // -----------------------------------------------------------------
    // 2. Do not run for Administrator
    // -----------------------------------------------------------------
    if (frappe.user.has_role("Administrator")) return;

    // -----------------------------------------------------------------
    // 3. Get current user roles (client-side, no extra call)
    // -----------------------------------------------------------------
    const userRoles = frappe.boot.user.roles || [];

    // -----------------------------------------------------------------
    // 4. Determine allowed workspaces
    // -----------------------------------------------------------------
    let allowed = ["Home"];                 // always keep Home
    for (const role in ROLE_WORKSPACES) {
        if (userRoles.includes(role)) {
            allowed = ROLE_WORKSPACES[role];
            break;                       // first matching role wins
        }
    }

    // -----------------------------------------------------------------
    // 5. Helper – normalise text
    // -----------------------------------------------------------------
    const norm = s => (s || "").trim();

    // -----------------------------------------------------------------
    // 6. Core hiding function
    // -----------------------------------------------------------------
    const hideUnwanted = () => {
        // ---- Sidebar items ------------------------------------------------
        document.querySelectorAll('.standard-sidebar-section .sidebar-item').forEach(itm => {
            const label = norm(itm.getAttribute('data-label'));
            itm.style.display = allowed.includes(label) ? '' : 'none';
        });

        // ---- Home-page workspace cards -----------------------------------
        document.querySelectorAll('.workspace-card-container').forEach(card => {
            const title = norm(card.querySelector('.workspace-title')?.innerText);
            if (title) {
                card.style.display = allowed.includes(title) ? '' : 'none';
            }
        });

        // ---- Hide empty sidebar sections ---------------------------------
        document.querySelectorAll('.standard-sidebar-section').forEach(sec => {
            const visible = sec.querySelectorAll('.sidebar-item[style=""], .sidebar-item:not([style])').length;
            if (visible === 0) sec.style.display = 'none';
        });
    };

    // -----------------------------------------------------------------
    // 7. Run several times (Frappe loads items async)
    // -----------------------------------------------------------------
    hideUnwanted();
    setTimeout(hideUnwanted, 600);
    setTimeout(hideUnwanted, 1200);
    setTimeout(hideUnwanted, 2000);
});
